actions.script:
filedCount = 0
try {
    filedCount = ec.resource.script('component://mr-mantle/service/mantle/marketing/MarketingAutomations.js').execute('orderPlaced', context).filedCount
} catch (error) {
    ec.message.clearErrors()
    ec.logger.error('Order ' + orderId + ': its automation events were not filed: ' + String(error.message).split('\n')[0])
}
// P20: the attribution, apart (a probe: its own transaction and error frame)
outcomeLinkId = null
try {
    outcomeLinkId = ec.resource.script('component://mr-mantle/service/mantle/ledger/EntityLib.js')
        .probe('mantle.marketing.TrackingServices.record#OrderAttribution', {orderId}).outcomeLinkId || null
} catch (error) {
    ec.logger.error('Order ' + orderId + ': its attribution waits for the attribution job: ' + String(error.message).split('\n')[0])
}
